/* HELIOS / HANGAR 07
   A procedural, offline Three.js scene. All geometry, textures and lighting are
   created here. The embedded vendor bundle above is Three.js r170 (MIT).
   Controls: drag / touch = orbit, wheel / pinch = zoom; F, C, Space, R, Esc.
*/
(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const { OrbitControls, EffectComposer, RenderPass, UnrealBloomPass, OutputPass, mergeGeometries } = window.HangarFX;
  const stage = $('stage'), canvas = $('viewport');
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const state = { formation:'wedge', paused:reducedMotion, cinematic:false, haze:.35, time:0, cameraTime:0, ready:false };
  const TAU = Math.PI * 2;
  const vec = (x,y,z) => new THREE.Vector3(x,y,z);
  const announce = (message) => { $('announcer').textContent = message; };
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias:true, powerPreference:'high-performance', alpha:false });
  } catch (error) {
    $('loading').innerHTML = '<div class="error-note">This hangar needs WebGL 2.<br>Enable hardware acceleration or open this file in a current browser, then reload.</div>';
    $('sim-label').textContent = 'GRAPHICS UNAVAILABLE';
    for (const control of document.querySelectorAll('button,input')) control.disabled = true;
    return;
  }
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.6));
  renderer.setSize(stage.clientWidth, stage.clientHeight);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.03;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x101b24);
  scene.fog = new THREE.FogExp2(0x162530, .0108);
  const camera = new THREE.PerspectiveCamera(49, stage.clientWidth / stage.clientHeight, .15, 180);
  const controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true; controls.dampingFactor = .055;
  controls.enablePan = false; controls.minDistance = 18; controls.maxDistance = 57;
  controls.minPolarAngle = .42; controls.maxPolarAngle = Math.PI / 2 - .055;
  controls.minAzimuthAngle = -1.26; controls.maxAzimuthAngle = 1.26;
  controls.rotateSpeed = .45; controls.zoomSpeed = .7;
  function homePosition(){ return stage.clientWidth < 720 ? vec(24,14,42) : vec(24,11.7,31); }
  function homeTarget(){ return vec(0,4.6,-12); }
  camera.position.copy(homePosition()); controls.target.copy(homeTarget()); controls.update();

  const composer = new EffectComposer(renderer);
  composer.addPass(new RenderPass(scene,camera));
  const bloom = new UnrealBloomPass(new THREE.Vector2(stage.clientWidth,stage.clientHeight), .46, .6, .93);
  composer.addPass(bloom); composer.addPass(new OutputPass());

  // Repeatable texture noise. No downloads, image assets, or font requests.
  let seed = 70042;
  function random(){ seed = (Math.imul(seed,1664525) + 1013904223) >>> 0; return seed / 4294967296; }
  function texture(width,height,paint){
    const c = document.createElement('canvas'); c.width=width; c.height=height;
