  }
  const floorTexture = texture(1024,1024,(ctx,w,h) => {
    ctx.fillStyle='#667073'; ctx.fillRect(0,0,w,h);
    for(let i=0;i<31000;i++){
      const n=Math.floor(80+random()*110); ctx.fillStyle=`rgba(${n},${n+2},${n+4},${random()*.1})`;
      ctx.fillRect(random()*w,random()*h,1+random()*3,1+random()*3);
    }
    ctx.lineWidth=2; ctx.strokeStyle='#424c50';
    for(let i=0;i<=4;i++){ctx.beginPath();ctx.moveTo(i*w/4,0);ctx.lineTo(i*w/4,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*h/4);ctx.lineTo(w,i*h/4);ctx.stroke();}
    ctx.strokeStyle='#94a2a31f';ctx.lineWidth=1;
    for(let i=0;i<900;i++){let x=random()*w,y=random()*h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+random()*32,y+random()*2);ctx.stroke();}
    for(let x=0;x<4;x++)for(let y=0;y<4;y++)for(const [dx,dy] of [[8,8],[248,8],[8,248],[248,248]]){
