    const g=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,w/2);g.addColorStop(0,'rgba(0,0,0,.68)');g.addColorStop(.35,'rgba(0,0,0,.48)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
  });
  const stripeTexture = texture(256,128,(ctx,w,h) => {
    ctx.fillStyle='#171b1b';ctx.fillRect(0,0,w,h);ctx.fillStyle='#c8893f';
    for(let x=-h;x<w+h;x+=64){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+32,0);ctx.lineTo(x+32+h,h);ctx.lineTo(x+h,h);ctx.fill();}
    ctx.fillStyle='#20292966';for(let i=0;i<3000;i++)ctx.fillRect(random()*w,random()*h,random()*5,1);
  });
  stripeTexture.wrapS=stripeTexture.wrapT=THREE.RepeatWrapping; stripeTexture.repeat.set(12,1);

  const metal = (color,roughness=.6,metalness=.55,extra={}) => new THREE.MeshStandardMaterial({color,roughness,metalness,...extra});
  const lightMaterial = (color,intensity=3) => metal(color,.3,.35,{emissive:color,emissiveIntensity:intensity});
  const materials = {
    floor:metal(0x434c50,.42,.65,{map:floorTexture,bumpMap:floorTexture,bumpScale:.035}),
    wall:metal(0x414f58,.79,.48,{map:wallTexture}),
    dark:metal(0x172127,.63,.65), ribs:metal(0x35434b,.5,.72),
    edge:metal(0x617079,.46,.72), black:metal(0x10181c,.77,.45),
    steel:metal(0x59686b,.4,.78), copper:metal(0x6b503d,.55,.75),
