const path = require('node:path');
const vm = require('node:vm');
const esbuild = require('esbuild');

(async () => {
  const result = await esbuild.build({
    entryPoints:[path.join(__dirname,'vendor-entry.js')],
    bundle:true, minify:true, format:'iife', target:'es2020',
    write:false, legalComments:'inline', logLevel:'warning'
  });
  const vendor = result.outputFiles[0].text;
  const app = fs.readFileSync(path.join(__dirname,'app.js'),'utf8');
  new vm.Script(vendor,{filename:'embedded-three.js'});
  new vm.Script(app,{filename:'hangar.js'});
  const license = fs.readFileSync(path.join(__dirname,'node_modules/three/LICENSE'),'utf8');
  const inlineSafe = text => text.replace(/<\/script/gi,'<\\/script');
  let html = fs.readFileSync(path.join(__dirname,'page.html'),'utf8');
  html = html.replace('/*__VENDOR__*/', () => `\n/*\nTHREE.JS r170 and bundled addons\n${license}\n*/\n${inlineSafe(vendor)}`)
             .replace('/*__APP__*/', () => '\n'+inlineSafe(app));
  if (/\/\*__\w+__\*\//.test(html)) throw new Error('Unfilled template marker');
  const destination = '/Users/alvin/claude-cowork/hangar-harness-model-tests/hangar-codex-astra60max/index.html';
  fs.writeFileSync(destination,html);
  console.log(`Created ${destination}\n${Buffer.byteLength(html).toLocaleString()} bytes · embedded Three.js r170 · no external assets`);
})();

