// Exercise the real scene geometry and control state without a browser or GPU.
const fs=require('node:fs');
const vm=require('node:vm');
const assert=require('node:assert/strict');
const THREE=require('three');

(async()=>{
  const {mergeGeometries}=await import('three/addons/utils/BufferGeometryUtils.js');
  const html=fs.readFileSync(__dirname+'/page.html','utf8');
  const elements=new Map();
  const paint=new Proxy({}, {get:(target,key)=>key.startsWith('create')?()=>({addColorStop(){}}):()=>{}});
  function element(id='',tagName='DIV'){
    return {id,tagName,clientWidth:1440,clientHeight:650,dataset:{},attributes:{},listeners:{},style:{setProperty(){}},classList:{add(){},remove(){},toggle(){}},setAttribute(k,v){this.attributes[k]=v},addEventListener(k,f){this.listeners[k]=f},getContext(){return paint},getRootNode(){return document},textContent:'',value:'35'};
  }
  for(const match of html.matchAll(/<([a-z]+)[^>]*\bid="([^"]+)"/g))elements.set(match[2],element(match[2],match[1].toUpperCase()));
  const buttons=['wedge','orbit','line'].map(name=>{const e=element('', 'BUTTON');e.dataset.formation=name;return e;});
  const listeners={};
  const document={hidden:false,addEventListener(k,f){listeners[k]=f},getElementById(id){assert(elements.has(id),`Missing DOM ID ${id}`);return elements.get(id)},querySelectorAll(selector){return selector==='[data-formation]'?buttons:[]},createElement(tag){return element('',tag.toUpperCase())}};
  let now=0,frames=[],capturedScene,capturedCamera;
  class Renderer {
    constructor(){this.shadowMap={};this.capabilities={getMaxAnisotropy:()=>8};this.info={render:{calls:0,triangles:0}};}
    setPixelRatio(){}setSize(){}
    compile(scene,camera){capturedScene=scene;capturedCamera=camera;let meshes=0,vertices=0;scene.traverse(obj=>{
      if(!obj.isMesh&&!obj.isPoints)return;meshes++;
      const position=obj.geometry.attributes.position;vertices+=position.count;
      assert(position.count>0,'Empty merged geometry');
      assert(position.array.every(Number.isFinite),'Non-finite geometry');
      obj.geometry.computeBoundingSphere();assert(Number.isFinite(obj.geometry.boundingSphere.radius),'Invalid bounding sphere');
      if(obj.geometry.index)assert(obj.geometry.index.array.every(i=>i<position.count),'Invalid geometry index');
    });console.log(`Scene initialized: ${meshes} meshes / point clouds, ${vertices.toLocaleString()} vertices; all geometry finite and indexed correctly.`);}
  }
  class OrbitControls {constructor(camera){this.camera=camera;this.target=new THREE.Vector3();}update(){this.camera.lookAt(this.target)}}
  class Composer {addPass(){}setSize(){}render(){}}
  class Pass{}
  const window={THREE:null,HangarFX:{OrbitControls,EffectComposer:Composer,RenderPass:Pass,UnrealBloomPass:Pass,OutputPass:Pass,mergeGeometries},addEventListener(){}};
  const context={console,document,window,THREE:{...THREE,WebGLRenderer:Renderer},devicePixelRatio:1,matchMedia:()=>({matches:false}),ResizeObserver:class{constructor(f){this.f=f}observe(){this.f()}},performance:{now:()=>now},requestAnimationFrame:(f)=>{frames.push(f);return frames.length},cancelAnimationFrame(){}};
  window.THREE=context.THREE;
  vm.runInNewContext(fs.readFileSync(__dirname+'/app.js','utf8'),context,{filename:'app.js',timeout:15000});
  function advance(seconds){for(let i=0;i<Math.ceil(seconds/.05);i++){now+=50;const queue=frames;frames=[];queue.forEach(f=>f(now));}}
  function button(id){elements.get(id).listeners.click();}
  advance(.2);assert.equal(window.hangarInfo.drones,5);assert.equal(window.hangarInfo.formation,'wedge');
  buttons[1].listeners.click();advance(10);assert.equal(window.hangarInfo.formation,'orbit');
  buttons[2].listeners.click();advance(12);assert.equal(window.hangarInfo.formation,'line');
  const drones=capturedScene.children.filter(o=>o.isGroup&&o.children.some(c=>c.isPointLight&&c.intensity===17));
  assert.equal(drones.length,5);
  assert(drones.every(d=>Math.abs(d.position.z+10.5)<.15),'Line formation did not converge');
  button('pause');const frozen=drones.map(d=>d.position.clone());advance(1);
  assert(window.hangarInfo.paused);drones.forEach((d,i)=>assert(d.position.equals(frozen[i]),'Paused drone moved'));
  button('pause');advance(.2);assert(!window.hangarInfo.paused);
  const fog=elements.get('fog');fog.listeners.input({target:{value:'83',style:{setProperty(){}}}});advance(.1);assert.equal(window.hangarInfo.haze,.83);
  const originalCamera=capturedCamera.position.clone();button('cinematic');advance(24);assert(window.hangarInfo.cinematic);assert(capturedCamera.position.distanceTo(originalCamera)>2);
  button('pause');const cameraFrozen=capturedCamera.position.clone();advance(1);assert(capturedCamera.position.equals(cameraFrozen));button('pause');
  advance(27);assert(!window.hangarInfo.cinematic);assert(capturedCamera.position.distanceTo(originalCamera)<.001,'Camera did not restore');
  const keyboard=listeners.keydown;keyboard({key:'f',target:elements.get('viewport'),preventDefault(){}});assert.equal(window.hangarInfo.formation,'wedge');
  button('reset-camera');advance(2);assert(capturedCamera.position.distanceTo(new THREE.Vector3(18,9.2,22))<.001);
  assert(drones.every(d=>d.position.toArray().every(Number.isFinite)));
  console.log('Passed: three formations, movement convergence, pause/resume, haze, keyboard shortcut, 48-second camera path, camera pause and restoration, reset view.');
  console.log('Scope: real Three.js geometry and animation/control logic; GPU rendering is not exercised.');
})();

